.hero h1 {
  font-size: var(--fs-4xl);
  font-weight: var(--fw-bold);
  margin-bottom: var(--space-sm);
  line-height: 1.15;
}

.hero .subtitle {
  font-size: var(--fs-lg);
  opacity: 0.9;
  margin-bottom: var(--space-xl);
  font-weight: var(--fw-regular);
}

/* Search Form */
.search-form {
  background: var(--color-gold);
  padding: 4px;
  border-radius: var(--radius-lg);
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  max-width: 900px;
}

.search-field {
  flex: 1 1 200px;
  min-width: 160px;
}

.search-field input,
.search-field select {
  width: 100%;
  padding: var(--space-md) var(--space-lg);
  border: none;
  border-radius: var(--radius-md);
  font-size: var(--fs-sm);
  color: var(--color-text);
  background: var(--color-white);
  height: 50px;
}

.search-field input::placeholder { color: var(--color-text-muted); }

.btn-search {
  background: var(--color-primary);
  color: var(--color-white);
  font-weight: var(--fw-bold);
  font-size: var(--fs-md);
  padding: var(--space-md) var(--space-xl);
  border-radius: var(--radius-md);
  transition: background var(--transition-fast);
  white-space: nowrap;
  height: 50px;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}
.btn-search:hover { background: var(--color-primary-dark); }

.search-options {
  margin-top: var(--space-md);
  display: flex;
  gap: var(--space-lg);
  flex-wrap: wrap;
}

.search-options label {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: var(--fs-sm);
  cursor: pointer;
  color: rgba(255,255,255,0.95);
}

.search-options input[type="checkbox"] {
  accent-color: var(--color-gold);
  width: 16px; height: 16px;
}

/* Package radio options */
.radio-group {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
  margin-bottom: var(--space-md);
}

.radio-option {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  cursor: pointer;
  font-size: var(--fs-sm);
  color: rgba(255,255,255,0.95);
}

.radio-option input[type="radio"] {
  accent-color: var(--color-gold);
  width: 16px; height: 16px;
}

/* ============================================
   TRUST BADGES
   ============================================ */
.trust-badges {
  padding: var(--space-2xl) 0;
  background: var(--color-bg);
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
}

.trust-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
}

.trust-icon {
  width: 40px; height: 40px;
  background: var(--color-primary);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.trust-icon svg { width: 20px; height: 20px; color: var(--color-white); }

.trust-item strong {
  display: block;
  font-size: var(--fs-sm);
  font-weight: var(--fw-bold);
  color: var(--color-text);
  margin-bottom: 2px;
}

.trust-item span {
  font-size: var(--fs-xs);
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* ============================================
   SECTION HEADINGS
   ============================================ */
.section-heading {
  margin-bottom: var(--space-xl);
}

.section-heading h2 {
  font-size: var(--fs-2xl);
  font-weight: var(--fw-bold);
  color: var(--color-text);
  line-height: 1.2;
}

.section-heading p {
  font-size: var(--fs-base);
  color: var(--color-text-secondary);
  margin-top: var(--space-xs);
}

/* ============================================
   OFFERS SECTION
   ============================================ */
.offers {
  padding: var(--space-3xl) 0;
}

.offers-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-lg);
}

.offer-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  min-height: 220px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: var(--space-xl);
  color: var(--color-white);
  background-size: cover;
  background-position: center;
}

.offer-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.65) 0%, rgba(0,0,0,0.1) 60%);
  z-index: 0;
}

.offer-card > * { position: relative; z-index: 1; }

.offer-card h3 {
  font-size: var(--fs-xl);
  font-weight: var(--fw-bold);
  margin-bottom: var(--space-xs);
}

.offer-card p {
  font-size: var(--fs-sm);
  opacity: 0.92;
  margin-bottom: var(--space-md);
  max-width: 400px;
}

.btn-offer {
  display: inline-block;
  background: var(--color-gold);
  color: var(--color-text);
  font-weight: var(--fw-semibold);
  font-size: var(--fs-sm);
  padding: var(--space-sm) var(--space-lg);
  border-radius: var(--radius-md);
  transition: background var(--transition-fast);
  cursor: pointer;
}
.btn-offer:hover { background: var(--color-gold-dark); }

/* ============================================
   PROPERTY TYPES
   ============================================ */
.property-types {
  padding: var(--space-3xl) 0;
  background: var(--color-bg);
}

.property-chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.property-chip {
  background: var(--color-white);
  border: 1px solid var(--color-border);
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-full);
  font-size: var(--fs-sm);
  color: var(--color-text-secondary);
  transition: all var(--transition-fast);
  cursor: pointer;
}
.property-chip:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
  background: var(--color-accent-light);
}

/* ============================================
   TRIP PLANNER TABS
   ============================================ */
.trip-planner {
  padding: var(--space-3xl) 0;
}

.tab-list {
  display: flex;
  gap: var(--space-xs);
  flex-wrap: wrap;
  margin-bottom: var(--space-xl);
  border-bottom: 2px solid var(--color-border-light);
  padding-bottom: 0;
}

.tab-btn {
  padding: var(--space-sm) var(--space-md);
  font-size: var(--fs-sm);
  font-weight: var(--fw-medium);
  color: var(--color-text-secondary);
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  transition: all var(--transition-fast);
  white-space: nowrap;
  cursor: pointer;
}

.tab-btn:hover {
  color: var(--color-primary);
}

.tab-btn.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
  font-weight: var(--fw-semibold);
}

.tab-panel { display: none; }
.tab-panel.active { display: block; }

.destination-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-md);
}

.destination-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--color-white);
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition-base);
  cursor: pointer;
}
.destination-card:hover { box-shadow: var(--shadow-md); }

.destination-card-img {
  height: 130px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  position: relative;
}

.destination-card-body {
  padding: var(--space-md);
}

.destination-card-body h4 {
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
  margin-bottom: 2px;
}

.destination-card-body span {
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
}

/* ============================================
   UNIQUE PROPERTIES CAROUSEL
   ============================================ */
.unique-properties {
  padding: var(--space-3xl) 0;
  background: var(--color-bg);
}

.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: var(--space-md);
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: var(--space-sm) 0;
}
.carousel-track::-webkit-scrollbar { display: none; }

.property-card {
  flex: 0 0 260px;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition-base);
}
.property-card:hover { box-shadow: var(--shadow-md); }

.property-card-img {
  height: 170px;
  background-size: cover;
  background-position: center;
  position: relative;
}

.property-card-body {
  padding: var(--space-md);
}

.property-card-body h4 {
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
  margin-bottom: 2px;
  line-height: 1.3;
}

.property-card-location {
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
  margin-bottom: var(--space-sm);
}

.property-card-rating {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  margin-bottom: var(--space-sm);
}

.rating-badge {
  background: var(--color-primary);
  color: var(--color-white);
  font-size: var(--fs-xs);
  font-weight: var(--fw-bold);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
}

.rating-text {
  font-size: var(--fs-xs);
  color: var(--color-text-secondary);
}

.rating-count {
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
}

.property-card-price {
  font-size: var(--fs-md);
  font-weight: var(--fw-bold);
  color: var(--color-text);
}

.price-original {
  text-decoration: line-through;
  color: var(--color-text-muted);
  font-weight: var(--fw-regular);
  font-size: var(--fs-sm);
  margin-right: var(--space-xs);
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px; height: 40px;
  background: var(--color-white);
  border-radius: var(--radius-full);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  transition: box-shadow var(--transition-fast);
  cursor: pointer;
}
.carousel-arrow:hover { box-shadow: var(--shadow-lg); }
.carousel-arrow svg { width: 20px; height: 20px; color: var(--color-text); }

.carousel-arrow.prev { left: -12px; }
.carousel-arrow.next { right: -12px; }

/* ============================================
   TRENDING DESTINATIONS
   ============================================ */
.trending {
  padding: var(--space-3xl) 0;
}

.trending-pills {
  display: flex;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.trending-pill {
  background: var(--color-accent-light);
  color: var(--color-primary);
  font-weight: var(--fw-semibold);
  font-size: var(--fs-base);
  padding: var(--space-sm) var(--space-lg);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}
.trending-pill:hover {
  background: var(--color-primary);
  color: var(--color-white);
}
.trending-pill svg { width: 16px; height: 16px; }

/* ============================================
   EXPLORE DESTINATIONS GRID
   ============================================ */
.explore-destinations {
  padding: var(--space-3xl) 0;
  background: var(--color-bg);
}

.explore-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-md);
}

.explore-card {
  background: var(--color-white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition-base);
  cursor: pointer;
  display: flex;
  align-items: center;
}
.explore-card:hover { box-shadow: var(--shadow-md); }

.explore-card-img {
  width: 80px; height: 80px;
  background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
  flex-shrink: 0;
}

.explore-card-body {
  padding: var(--space-md);
}

.explore-card-body h4 {
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
}

.explore-card-body span {
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
}

/* ============================================
   WEEKEND DEALS
   ============================================ */
.weekend-deals {
  padding: var(--space-3xl) 0;
}

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: var(--space-md);
}

.deal-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border-light);
  transition: box-shadow var(--transition-base);
}
.deal-card:hover { box-shadow: var(--shadow-md); }

.deal-card-img {
  height: 160px;
  background-size: cover;
  background-position: center;
  position: relative;
}

.sale-badge {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  background: var(--color-sale);
  color: var(--color-white);
  font-size: var(--fs-xs);
  font-weight: var(--fw-bold);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
}

.deal-card-body {
  padding: var(--space-md);
}

.deal-card-body h4 {
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
  margin-bottom: 2px;
}

.deal-card-location {
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
  margin-bottom: var(--space-sm);
}

.deal-card-rating {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  margin-bottom: var(--space-sm);
}

.deal-price-row {
  display: flex;
  align-items: baseline;
  gap: var(--space-sm);
}

.deal-original {
  text-decoration: line-through;
  color: var(--color-text-muted);
  font-size: var(--fs-sm);
}

.deal-sale {
  font-size: var(--fs-md);
  font-weight: var(--fw-bold);
  color: var(--color-sale);
}

.deal-duration {
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
}

/* ============================================
   HOMES GUESTS LOVE
   ============================================ */
.homes-guests {
  padding: var(--space-3xl) 0;
  background: var(--color-bg);
}

.homes-link {
  display: inline-block;
  margin-top: var(--space-md);
  color: var(--color-accent);
  font-weight: var(--fw-semibold);
  font-size: var(--fs-sm);
}
.homes-link:hover { text-decoration: underline; }

.homes-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: var(--space-md);
}

/* ============================================
   LOYALTY CTA
   ============================================ */
.loyalty-cta {
  padding: var(--space-3xl) 0;
}

.loyalty-card {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-accent) 100%);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl) var(--space-xl);
  color: var(--color-white);
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}

.loyalty-card h3 {
  font-size: var(--fs-2xl);
  font-weight: var(--fw-bold);
  margin-bottom: var(--space-xs);
}

.loyalty-card .sub {
  font-size: var(--fs-md);
  opacity: 0.9;
  margin-bottom: var(--space-sm);
}

.loyalty-card p {
  font-size: var(--fs-sm);
  opacity: 0.85;
  margin-bottom: var(--space-lg);
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

.loyalty-actions {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
}

.btn-loyalty-primary {
  background: var(--color-gold);
  color: var(--color-text);
  font-weight: var(--fw-semibold);
  padding: var(--space-sm) var(--space-xl);
  border-radius: var(--radius-md);
  transition: background var(--transition-fast);
  cursor: pointer;
}
.btn-loyalty-primary:hover { background: var(--color-gold-dark); }

.btn-loyalty-secondary {
  background: rgba(255,255,255,0.15);
  color: var(--color-white);
  font-weight: var(--fw-semibold);
  padding: var(--space-sm) var(--space-xl);
  border-radius: var(--radius-md);
  border: 1px solid rgba(255,255,255,0.3);
  transition: all var(--transition-fast);
  cursor: pointer;
}
.btn-loyalty-secondary:hover { background: rgba(255,255,255,0.25); }

/* ============================================
   POPULAR LINKS TABS
   ============================================ */
.popular-links {
  padding: var(--space-3xl) 0;
  background: var(--color-bg);
}

.links-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-sm) var(--space-lg);
}

.links-grid a {
  font-size: var(--fs-sm);
  color: var(--color-text-secondary);
  padding: var(--space-xs) 0;
  transition: color var(--transition-fast);
}
.links-grid a:hover { color: var(--color-accent); }

/* ============================================
   FOOTER
   ============================================ */
.site-footer {
  background: var(--color-text);
  color: rgba(255,255,255,0.7);
  padding: var(--space-3xl) 0 var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-xl);
  margin-bottom: var(--space-2xl);
}

.footer-col h5 {
  color: var(--color-white);
  font-size: var(--fs-sm);
  font-weight: var(--fw-bold);
  margin-bottom: var(--space-md);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.footer-col a {
  display: block;
  font-size: var(--fs-xs);
  color: rgba(255,255,255,0.6);
  padding: 3px 0;
  transition: color var(--transition-fast);
}
.footer-col a:hover { color: var(--color-white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: var(--space-lg);
  font-size: var(--fs-xs);
  color: rgba(255,255,255,0.4);
  line-height: 1.6;
}

/* ============================================
   PACKAGES PAGE — BENEFITS
   ============================================ */
.benefits {
  padding: var(--space-3xl) 0;
}

.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.benefit-item {
  text-align: center;
  padding: var(--space-xl);
  border-radius: var(--radius-lg);
  background: var(--color-bg);
}

.benefit-icon {
  width: 56px; height: 56px;
  background: var(--color-accent-light);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-md);
}
.benefit-icon svg { width: 28px; height: 28px; color: var(--color-primary); }

.benefit-item h4 {
  font-size: var(--fs-md);
  font-weight: var(--fw-semibold);
  margin-bottom: var(--space-xs);
}

.benefit-item p {
  font-size: var(--fs-sm);
  color: var(--color-text-secondary);
}

/* ============================================
   POPULAR DESTINATIONS (Packages / Car Rental)
   ============================================ */
.popular-destinations {
  padding: var(--space-3xl) 0;
}

.dest-table-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--space-md);
}

.dest-table-item {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--color-bg);
  border-radius: var(--radius-md);
  transition: background var(--transition-fast);
  cursor: pointer;
}
.dest-table-item:hover { background: var(--color-accent-light); }

.dest-table-item-img {
  width: 60px; height: 60px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%);
  flex-shrink: 0;
}

.dest-table-item-body h4 {
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
}

.dest-table-item-body span {
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
}

/* ============================================
   RENTAL COMPANIES
   ============================================ */
.rental-companies {
  padding: var(--space-3xl) 0;
  background: var(--color-bg);
}

.company-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: var(--space-md);
}

.company-logo {
  background: var(--color-white);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  padding: var(--space-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  height: 80px;
  font-weight: var(--fw-bold);
  font-size: var(--fs-md);
  color: var(--color-text-secondary);
  transition: border-color var(--transition-fast);
}
.company-logo:hover { border-color: var(--color-accent); }

/* ============================================
   CREDIT CARD PROMO
   ============================================ */
.credit-promo {
  padding: var(--space-3xl) 0;
}

.credit-card {
  background: linear-gradient(135deg, #1a1a2e 0%, #003B95 100%);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  color: var(--color-white);
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.credit-card-text h3 {
  font-size: var(--fs-xl);
  font-weight: var(--fw-bold);
  margin-bottom: var(--space-sm);
}

.credit-card-text p {
  font-size: var(--fs-sm);
  opacity: 0.85;
  margin-bottom: var(--space-md);
}

.credit-card-icon {
  width: 100px; height: 70px;
  background: var(--color-gold);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: var(--fw-bold);
  color: var(--color-text);
  font-size: var(--fs-xs);
  flex-shrink: 0;
}

/* ============================================
   FAQ ACCORDION
   ============================================ */
.faq {
  padding: var(--space-3xl) 0;
  background: var(--color-bg);
}

.faq-list {
  max-width: 800px;
}

.faq-item {
  background: var(--color-white);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-sm);
  overflow: hidden;
}

.faq-question {
  width: 100%;
  text-align: left;
  padding: var(--space-md) var(--space-lg);
  font-weight: var(--fw-semibold);
  font-size: var(--fs-sm);
  color: var(--color-text);
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: background var(--transition-fast);
  cursor: pointer;
}

.faq-question:hover { background: var(--color-bg); }

.faq-question svg {
  width: 20px; height: 20px;
  color: var(--color-text-muted);
  transition: transform var(--transition-base);
  flex-shrink: 0;
}

.faq-item.open .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.faq-answer-inner {
  padding: 0 var(--space-lg) var(--space-md);
  font-size: var(--fs-sm);
  color: var(--color-text-secondary);
  line-height: 1.6;
}

/* ============================================
   CAR RENTAL DESTINATIONS TABLE
   ============================================ */
.rental-dest-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--space-md);
}

.rental-dest-card {
  background: var(--color-white);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  padding: var(--space-md);
  transition: border-color var(--transition-fast);
  cursor: pointer;
}
.rental-dest-card:hover { border-color: var(--color-accent); }

.rental-dest-card h4 {
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
  margin-bottom: 2px;
}

.rental-dest-card .locations {
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
}

.rental-dest-card .price {
  font-size: var(--fs-md);
  font-weight: var(--fw-bold);
  color: var(--color-primary);
  margin-top: var(--space-sm);
}

.rental-dest-card .price-label {
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
  font-weight: var(--fw-regular);
}

/* ============================================
   ATTRACTIONS — RECOMMENDED
   ============================================ */
.recommended {
  padding: var(--space-3xl) 0;
}

.activity-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: var(--space-md);
}

.activity-card {
  display: flex;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--color-bg);
  border-radius: var(--radius-md);
  transition: background var(--transition-fast);
  cursor: pointer;
}
.activity-card:hover { background: var(--color-accent-light); }

.activity-card-img {
  width: 80px; height: 80px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  flex-shrink: 0;
}

.activity-card-body h4 {
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
  margin-bottom: 4px;
}

.activity-card-body .activity-type {
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
}

.activity-card-body .activity-price {
  font-size: var(--fs-sm);
  font-weight: var(--fw-bold);
  color: var(--color-primary);
  margin-top: var(--space-xs);
}

/* ============================================
   ATTRACTIONS — NEARBY DESTINATIONS
   ============================================ */
.nearby-destinations {
  padding: var(--space-3xl) 0;
  background: var(--color-bg);
}

.nearby-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-md);
}

.nearby-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-white);
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition-base);
  cursor: pointer;
}
.nearby-card:hover { box-shadow: var(--shadow-md); }

.nearby-card-img {
  height: 120px;
  background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
}

.nearby-card-body {
  padding: var(--space-md);
}

.nearby-card-body h4 {
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
}

.nearby-card-body span {
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
}

/* ============================================
   ATTRACTIONS — EXPLORE CITIES (Region Tabs)
   ============================================ */
.explore-cities {
  padding: var(--space-3xl) 0;
}

.cities-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: var(--space-md);
}

.city-chip {
  background: var(--color-bg);
  border-radius: var(--radius-md);
  padding: var(--space-md);
  text-align: center;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.city-chip:hover {
  background: var(--color-accent-light);
  border-color: var(--color-accent);
}

.city-chip h4 {
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
}

.city-chip span {
  font-size: var(--fs-xs);
  color: var(--color-text-muted);
}

/* ============================================
   ATTRACTIONS — THINGS TO DO
   ============================================ */
.things-to-do {
  padding: var(--space-3xl) 0;
  background: var(--color-bg);
}

.activity-links {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm) var(--space-md);
}

.activity-link {
  font-size: var(--fs-sm);
  color: var(--color-text-secondary);
  padding: var(--space-xs) 0;
  transition: color var(--transition-fast);
  cursor: pointer;
}
.activity-link:hover { color: var(--color-accent); text-decoration: underline; }

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 1024px) {
  .trust-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .benefits-grid { grid-template-columns: 1fr; max-width: 500px; margin: 0 auto; }
}

@media (max-width: 768px) {
  :root {
    --fs-4xl: 2rem;
    --fs-3xl: 1.75rem;
    --fs-2xl: 1.5rem;
  }

  .header-inner {
    flex-wrap: wrap;
    height: auto;
    padding: var(--space-sm) var(--space-md);
    gap: var(--space-sm);
  }

  .nav-tabs { order: 3; width: 100%; padding-bottom: 0; }
  .header-actions { margin-left: 0; }

  .hero { padding: var(--space-xl) 0; }

  .search-form {
    flex-direction: column;
    gap: 4px;
  }

  .search-field { flex: 1 1 auto; min-width: 0; }

  .offers-grid { grid-template-columns: 1fr; }
  .trust-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }

  .credit-card { flex-direction: column; text-align: center; }

  .tab-list { overflow-x: auto; }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-md); }
  .hero h1 { font-size: 1.75rem; }

  .destination-grid { grid-template-columns: repeat(2, 1fr); }
  .explore-grid { grid-template-columns: 1fr; }
  .deals-grid { grid-template-columns: 1fr; }
  .homes-grid { grid-template-columns: 1fr; }
  .nearby-grid { grid-template-columns: repeat(2, 1fr); }
  .cities-grid { grid-template-columns: repeat(2, 1fr); }

  .footer-grid { grid-template-columns: 1fr; }
}

/* ============================================
   REDUCED MOTION
   ============================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
